import pysat
from pysat.solvers import Glucose3
from pysat.card import CardEnc, EncType

N = 22

# Fixed assignments
fixed = {11: 8, 16: 14, 18: 11, 21: 13}

# Variables: x[i][j] for row i, column j
# We'll use integer variables: i*N + j + 1 (1-indexed for pysat)
def var(i, j):
    return i * N + j + 1

# Create solver
solver = Glucose3()

# Add variables (we'll add them as we use them)
# Actually, we need to allocate variables. Let's just add constraints.

# Row constraints: exactly one per row
for i in range(N):
    clause = [var(i, j) for j in range(N)]
    # Exactly one: at least one (clause) and at most one (pairwise)
    solver.add_clause(clause)  # at least one
    # At most one: pairwise negative
    for j1 in range(N):
        for j2 in range(j1+1, N):
            solver.add_clause([-var(i, j1), -var(i, j2)])

# Column constraints: at most one per column
for j in range(N):
    for i1 in range(N):
        for i2 in range(i1+1, N):
            solver.add_clause([-var(i1, j), -var(i2, j)])

# Diagonal constraints: at most one per diagonal
# Main diagonal: i - j constant
for d in range(-N+1, N):
    # cells with i - j = d
    cells = []
    for i in range(N):
        j = i - d
        if 0 <= j < N:
            cells.append((i, j))
    for a in range(len(cells)):
        for b in range(a+1, len(cells)):
            i1, j1 = cells[a]
            i2, j2 = cells[b]
            solver.add_clause([-var(i1, j1), -var(i2, j2)])

# Anti diagonal: i + j constant
for s in range(0, 2*N-1):
    cells = []
    for i in range(N):
        j = s - i
        if 0 <= j < N:
            cells.append((i, j))
    for a in range(len(cells)):
        for b in range(a+1, len(cells)):
            i1, j1 = cells[a]
            i2, j2 = cells[b]
            solver.add_clause([-var(i1, j1), -var(i2, j2)])

# Fixed assignments
for i, j in fixed.items():
    solver.add_clause([var(i, j)])

print("Solving...")
result = solver.solve()
print("Result:", result)
if result:
    model = solver.get_model()
    # Decode
    solution = [None] * N
    for i in range(N):
        for j in range(N):
            if var(i, j) in model:
                solution[i] = j
                break
    print("Solution:", solution)
    # Verify
    ok = True
    for i in range(N):
        for k in range(i+1, N):
            if solution[i] == solution[k] or abs(solution[i] - solution[k]) == abs(i - k):
                ok = False
                print(f"Conflict: ({i},{solution[i]}) vs ({k},{solution[k]})")
    print("Valid:", ok)
else:
    print("UNSAT")

solution = [15, 5, 7, 10, 18, 6, 17, 20, 4, 19, 16, 8, 21, 12, 3, 9, 14, 1, 11, 2, 0, 13]
N = 22

# Check fixed assignments
fixed = {11: 8, 16: 14, 18: 11, 21: 13}
for i, j in fixed.items():
    assert solution[i] == j, f"Fixed assignment violated: q[{i}] should be {j}, got {solution[i]}"

# Check no attacks
ok = True
for i in range(N):
    for k in range(i+1, N):
        if solution[i] == solution[k] or abs(solution[i] - solution[k]) == abs(i - k):
            print(f"Conflict: ({i},{solution[i]}) vs ({k},{solution[k]})")
            ok = False
if ok:
    print("Solution is valid!")
else:
    print("Solution invalid!")

# Print board
for i in range(N):
    line = ""
    for j in range(N):
        if solution[i] == j:
            line += "Q "
        else:
            line += ". "
    print(f"{i:2d}: {line}")
